function validate([nums, goal]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 30000) return 'nums needs 1 to 30000 values.';
  if (nums.some(v => v !== 0 && v !== 1)) return 'Each value of nums is 0 or 1.';
  if (!Number.isInteger(goal) || goal < 0 || goal > nums.length) return 'goal is between 0 and nums.length.';
  return null;
}

