function numSubarraysWithSum(nums, goal) {
  const count = new Array(nums.length + 1).fill(0);
  count[0] = 1;
  let prefix = 0;
  let total = 0;

  for (const num of nums) {
    prefix += num;
    if (prefix >= goal) {
      total += count[prefix - goal];
    }
    count[prefix]++;
  }
  return total;
}

