function numSubarraysWithSum(nums, goal) {
  let total = 0;
  for (let start = 0; start < nums.length; start++) {
    let sum = 0;
    for (let end = start; end < nums.length; end++) {
      sum += nums[end];
      if (sum === goal) total++;
    }
  }
  return total;
}

