function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const density = [0, 0.1, 0.5, 0.9, 1][Math.floor(rand() * 5)];
  const nums = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  const ones = nums.reduce((a, b) => a + b, 0);
  let goal;
  const pick = rand();
  if (pick < 0.15) goal = 0;
  else if (pick < 0.85) goal = Math.floor(rand() * (Math.min(ones, large ? 40 : ones) + 1));
  else goal = Math.floor(rand() * (n + 1));
  return [nums, goal];
}
